function oc_generate_vendor(): void {
	set_time_limit(600);
	ini_set('memory_limit', '512M');

	// Быстрый выход: если vendor.php уже сгенерирован и composer.json не менялись.
	$vendor_file = DIR_SYSTEM . 'vendor.php';
	$composer_files = glob(DIR_STORAGE . 'vendor/*/*/composer.json');
	$newest = 0;
	foreach ($composer_files as $cf) {
		$t = @filemtime($cf);
		if ($t !== false && $t > $newest) $newest = $t;
	}
	if (is_file($vendor_file)) {
		$vt = @filemtime($vendor_file);
		if ($vt !== false && $vt >= $newest) {
			return;
		}
	}

	$code = '<?php' . "\n";
